function sumPositive(numbers) {
  let total = 0;
  for (const n of numbers) {
    if (n > 0) {
      total += n;
    }
  }
  return total;
}

def greet(name, times=1):
    """Return a friendly greeting repeated `times` times."""
    lines = []
    for _ in range(times):
        lines.append(f"Hello, {name}!")
    return "\n".join(lines)

fn clamp_to_range(value: i32, low: i32, high: i32) -> i32 {
    if value < low {
        low
    } else if value > high {
        high
    } else {
        value
    }
}

